  $m=$this->json($manifestPath);if(($m['schema']??null)!==1||($m['base']??null)!==$base||($m['target']??null)!==$v||($m['base_digest']??null)!==$rows[$base]['digest']||($m['target_digest']??null)!==$row['digest']||!is_array($m['files']??null)||!isset($m['files']['changes.json']))throw new RuntimeException('comparison manifest mismatch');return [$derived,$m['files'],''];
 }
