 public function delta(string $v,string $key,?string $base=null,?string $parent=null):array{if(!preg_match('/^[a-f0-9]{64}$/D',$key))throw new InvalidArgumentException('diff');$rec=$this->comparisonRecord($v,$base,$parent);if($rec===null)throw new RuntimeException('comparison unavailable');[$dir,$hashes,$prefix]=$rec;$name='diffs/'.$key.'.json';if(!isset($hashes[$prefix.$name]))throw new RuntimeException('diff hash missing');return $this->verifiedJson(rtrim($dir,'/').'/'.$name,$hashes[$prefix.$name]);}
